    @Test
    void observationConflictRejectsWholeBatchAtomically() throws Exception {
        uploadBatch("batch-x1", "op-1", List.of(
                        createMessage("dev-1", "s-1", 1, "obs-a", "站点A", "1.0", "首条")))
                .andExpect(status().isOk());

